123	fn str_arg<'a>(args: &'a Value, key: &str) -> Result<&'a str, String> {
124	    args.get(key)
125	        .and_then(Value::as_str)
126	        .ok_or_else(|| format!("missing required string argument '{key}'"))
127	}
