202	/// `GET /v1/runs` → 200.
203	pub async fn list_runs(
204	    State(state): State<ServerState>,
205	    Query(query): Query<ListQuery>,
206	) -> Result<Json<ListResponse>, ServeError> {
207	    let page = state
208	        .history()
209	        .list(&query.into_filter())
210	        .await
