872	            }
873	        }
874	    }
875	    if processed < ids.len() {
876	        let mut stuck: Vec<String> = (0..ids.len())
877	            .filter(|&i| in_degree[i] > 0)
878	            .map(|i| ids[i].clone())
879	            .collect();
880	        stuck.sort();
881	        return Err(CliError::DependencyCycle { ids: stuck });
882	    }
883	    Ok(())
884	}
