42	/// Install a tracing subscriber that writes to **stderr** — stdout is reserved
43	/// for the JSON-RPC message stream in `faucet mcp` (stdio) mode.
44	pub fn install_stderr_tracing(level: &str) {
45	    use tracing_subscriber::EnvFilter;
46	    let filter = EnvFilter::try_new(level).unwrap_or_else(|_| EnvFilter::new("info"));
