112	/// Drive an MCP session over any byte streams: read newline-delimited JSON-RPC
113	/// from `reader`, write each response (one JSON object per line) to `writer`.
114	/// Blank lines are skipped; notifications produce no output. Returns when the
115	/// reader hits EOF. The `faucet mcp` stdio command wraps stdin/stdout with
116	/// this; tests drive it with in-memory buffers.
117	pub async fn serve_stdio<R, W>(ctx: &McpContext, reader: R, writer: &mut W) -> std::io::Result<()>
118	where
119	    R: tokio::io::AsyncBufRead + Unpin,
120	    W: tokio::io::AsyncWrite + Unpin,
121	{
122	    use tokio::io::{AsyncBufReadExt, AsyncWriteExt};
123	    let mut lines = reader.lines();
124	    while let Some(line) = lines.next_line().await? {
125	        let trimmed = line.trim();
126	        if trimmed.is_empty() {
127	            continue;
128	        }
129	        if let Some(response) = handle_message(ctx, trimmed).await {
130	            writer.write_all(response.as_bytes()).await?;
131	            writer.write_all(b"\n").await?;
132	            writer.flush().await?;
133	        }
134	    }
135	    Ok(())
136	}
