/// The reserved tag naming a template's newest version. Always resolvable, on
/// every template, and always what an unpinned request gets — so
/// `version=latest`, `--version latest`, and omitting the selector entirely are
/// three spellings of the same thing.
pub const LATEST_TAG: &str = "latest";

/// Which version of a template to use.
///
/// Omitting the selector, passing the [`LATEST_TAG`], or pinning a number are the
/// three forms every surface accepts. `Latest` is the default so a caller that
/// says nothing rides the newest registration — the point of versioning here is
/// that *iterating* a template is safe, not that callers must track numbers.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum VersionSelector {
    /// The newest registered version (`latest`).
    #[default]
    Latest,
    /// An exact version, for a pinned or rolled-back run.
    Pinned(u32),
}

impl VersionSelector {
    /// Parse `latest` (any case) or a positive integer.
    pub fn parse(raw: &str) -> CliResult<Self> {
        let s = raw.trim();
        if s.eq_ignore_ascii_case(LATEST_TAG) {
            return Ok(Self::Latest);
        }
        match s.parse::<u32>() {
            Ok(0) | Err(_) => Err(CliError::Config(format!(
                "invalid template version '{raw}' — expected `{LATEST_TAG}` or a version number \
                 (1, 2, …)"
            ))),
            Ok(n) => Ok(Self::Pinned(n)),
        }
    }

    /// The exact version to look up, or `None` for "whatever is newest" — the
    /// shape [`RunHistory::template_get`](super::RunHistory::template_get) takes.
    pub fn pinned(self) -> Option<u32> {
        match self {
            Self::Latest => None,
            Self::Pinned(n) => Some(n),
        }
    }
}

impl std::fmt::Display for VersionSelector {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Latest => f.write_str(LATEST_TAG),
            Self::Pinned(n) => write!(f, "{n}"),
        }
    }
}

// Accepts a JSON/query value in any of the natural spellings — `"latest"`, `"3"`,
// or the bare number `3` — so an HTTP query string, a JSON body, and an MCP tool
// argument all deserialize the same way.
impl<'de> Deserialize<'de> for VersionSelector {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        struct V;
        impl serde::de::Visitor<'_> for V {
            type Value = VersionSelector;
            fn expecting(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                write!(f, "\"{LATEST_TAG}\" or a version number")
            }
            fn visit_str<E: serde::de::Error>(self, s: &str) -> Result<Self::Value, E> {
                VersionSelector::parse(s).map_err(serde::de::Error::custom)
            }
            fn visit_u64<E: serde::de::Error>(self, n: u64) -> Result<Self::Value, E> {
                VersionSelector::parse(&n.to_string()).map_err(serde::de::Error::custom)
            }
            fn visit_i64<E: serde::de::Error>(self, n: i64) -> Result<Self::Value, E> {
                VersionSelector::parse(&n.to_string()).map_err(serde::de::Error::custom)
            }
        }
        d.deserialize_any(V)
    }
}

impl Serialize for VersionSelector {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&self.to_string())
    }
}

