// Minimal CDP driver: navigate, click/evaluate, screenshot, collect console errors.
import { writeFileSync } from "node:fs";

const PORT = process.env.CDP_PORT || "9333";
const BASE = process.env.APP || "http://127.0.0.1:8791";
const OUT = process.env.OUT || ".";

const targets = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
const page = targets.find((t) => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));

let id = 0;
const pending = new Map();
const errors = [];
ws.onmessage = (ev) => {
  const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) {
    pending.get(m.id)(m);
    pending.delete(m.id);
  }
  if (m.method === "Runtime.consoleAPICalled" && m.params.type === "error") {
    errors.push(m.params.args.map((a) => a.value || a.description).join(" "));
  }
  if (m.method === "Runtime.exceptionThrown") {
    errors.push("EXCEPTION " + JSON.stringify(m.params.exceptionDetails.text) + " " +
      (m.params.exceptionDetails.exception?.description || ""));
  }
};
const send = (method, params = {}) =>
  new Promise((res) => {
    const i = ++id;
    pending.set(i, res);
    ws.send(JSON.stringify({ id: i, method, params }));
  });

await send("Runtime.enable");
await send("Page.enable");

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const evaluate = async (expr) => {
  const r = await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true });
  if (r.result?.exceptionDetails) errors.push("EVAL " + r.result.exceptionDetails.text);
  return r.result?.result?.value;
};
const go = async (hash) => {
  await send("Page.navigate", { url: `${BASE}/${hash}` });
  await sleep(1200);
};
const shot = async (name, height = 1400) => {
  await send("Emulation.setDeviceMetricsOverride", { width: 1280, height, deviceScaleFactor: 1, mobile: false });
  const r = await send("Page.captureScreenshot", { format: "png" });
  writeFileSync(`${OUT}/${name}.png`, Buffer.from(r.result.data, "base64"));
};

// ── 1. draft template: the notice + refusal-to-run path ─────────────────────
await go("#/templates/customer-sync");
await shot("draft");
console.log("draft trigger choices:", await evaluate(
  `[...document.querySelectorAll('#tg-version option')].map(o=>o.textContent).join('|')`));

// ── 2. deprecated template notice ───────────────────────────────────────────
await go("#/templates/legacy-dump");
await shot("deprecated", 1200);

// ── 3. assign a channel from the versions page (v1 → canary) ────────────────
await go("#/templates/orders-export");
await evaluate(`(() => {
  const rows = [...document.querySelectorAll('.tpl-version')];
  const v1 = rows.find(r => r.querySelector('.tpl-vnum').textContent === 'v1');
  const sel = v1.querySelector('.tpl-assign');
  sel.value = 'canary';
  sel.dispatchEvent(new Event('change'));
})()`);
await sleep(1200);
console.log("after assign, v1 channels:", await evaluate(
  `[...document.querySelectorAll('.tpl-version')].find(r=>r.querySelector('.tpl-vnum').textContent==='v1')
     .querySelector('.tpl-vchannels').textContent.trim()`));

// ── 4. expand a version's config ────────────────────────────────────────────
await evaluate(`(() => {
  const rows = [...document.querySelectorAll('.tpl-version')];
  rows.find(r => r.querySelector('.tpl-vnum').textContent === 'v2').querySelector('.tpl-view').click();
})()`);
await sleep(700);
await shot("assigned");

// ── 5. launch v1, then roll back ────────────────────────────────────────────
await evaluate(`(() => {
  const rows = [...document.querySelectorAll('.tpl-version')];
  rows.find(r => r.querySelector('.tpl-vnum').textContent === 'v1').querySelector('.tpl-launch').click();
})()`);
await sleep(1300);
console.log("live after launch v1:", await evaluate(
  `document.querySelectorAll('.detail-grid > div')[1].querySelector('b').textContent`));
await shot("launched-v1");

await evaluate(`document.querySelector('#t-rollback').click()`);
await sleep(1300);
console.log("live after rollback:", await evaluate(
  `document.querySelectorAll('.detail-grid > div')[1].querySelector('b').textContent`));

// ── 6. trigger a run from the form ──────────────────────────────────────────
await evaluate(`(() => {
  document.querySelector('[data-name=table]').value = 'orders';
  document.querySelector('[data-name=api_key]').value = 'sekrit';
  document.querySelector('[data-name=limit]').value = '5';
  document.querySelector('#tg-version').value = 'stable';
  document.querySelector('#tg-go').click();
})()`);
await sleep(2000);
console.log("after trigger, hash:", await evaluate(`location.hash`));
await shot("triggered", 1200);

// ── 7. the list page ────────────────────────────────────────────────────────
await go("#/templates");
await shot("list", 620);

console.log("CONSOLE ERRORS:", errors.length ? errors : "none");
ws.close();

